#include <iostream>
#include <string>
#include <utility>
#include <vector>
using namespace std;

struct S {
    string name;
    static int copies, moves;
    explicit S(string n) : name(std::move(n)) {}
    S(const S& o) : name(o.name) { ++copies; }
    S(S&& o) noexcept : name(std::move(o.name)) { ++moves; }
};
int S::copies = 0;
int S::moves = 0;

int main() {
    S a("A");

    S::copies = S::moves = 0;
    S b = a;                       // 左值 → 拷贝构造
    cout << "S b = a;            copies=" << S::copies << " moves=" << S::moves << "\n";

    S::copies = S::moves = 0;
    S c = std::move(a);            // 右值 → 移动构造
    cout << "S c = move(a);      copies=" << S::copies << " moves=" << S::moves << "\n";

    S::copies = S::moves = 0;
    vector<S> v;
    v.reserve(4);                  // 预留容量，排除扩容干扰
    v.push_back(S("temp"));        // 临时对象 → 移动构造
    cout << "push_back(S(temp))  copies=" << S::copies << " moves=" << S::moves << "\n";
    (void)b; (void)c;
}
